// Per-action gate, evaluated again before every bubble, in this order:
// captured state, blocks (an appointment block admits only its own reminder
// and single confirmation), appointment checks, then a newer lead message.
// A newer lead message discards the unsent remainder and reprocesses the
// batch; sent actions and executed tools are never repeated. This harness
// has no provider credential, so an allowed action still ends observe_only.
const state = {
  state_version: 3,
  delivery_epoch: 3,
  lead_message_seq: 2,
  blocks: [{ type: 'appointment', source_ref: 'synthetic-appointment-1', active: true }],
  appointments: [{ ref: 'synthetic-appointment-1', status: 'confirmed', starts_at: '2026-10-09T13:00:00.000Z', confirmation_action_id: null }],
};
const now = Date.parse('2026-10-08T12:02:00.000Z');
const actions = [
  { action_id: 'synthetic-a2', kind: 'appointment_confirmation', source_ref: 'synthetic-appointment-1', captured_state_version: 3, captured_delivery_epoch: 3, lead_cutoff_seq: 1 },
];
const bound = new Set(['appointment_reminder', 'appointment_confirmation']);
function evaluate(action) {
  if (action.captured_state_version !== state.state_version || action.captured_delivery_epoch !== state.delivery_epoch) return 'state_changed';
  if (state.blocks.some(b => b.active && !(b.type === 'appointment' && bound.has(action.kind) && b.source_ref === action.source_ref))) return 'blocked';
  if (bound.has(action.kind)) {
    const appointment = state.appointments.find(a => a.ref === action.source_ref);
    if (!appointment) return 'appointment_not_found';
    if (appointment.status === 'cancelled') return 'appointment_cancelled';
    if (Date.parse(appointment.starts_at) <= now) return 'appointment_started';
    if (action.kind === 'appointment_confirmation' && appointment.confirmation_action_id && appointment.confirmation_action_id !== action.action_id) return 'appointment_confirmation_already_sent';
  }
  if (action.lead_cutoff_seq !== undefined && state.lead_message_seq > action.lead_cutoff_seq) return 'superseded_by_new_message';
  return 'observe_only';
}
const decisions = actions.map(a => ({ action_id: a.action_id, reason: evaluate(a) }));
return [{ json: { permission_checked: true, checked_before_each_action: true, allowed: false, decisions, reprocess_batch: decisions.some(d => d.reason === 'superseded_by_new_message'), sent_actions_repeated: false, reason: 'observe_only', simulated: true } }];
